def nbhbvs(board, colors, x, y):
    # Define shapes and their relative positions
    shapes = ['nut', 'bridge-h', 'bridge-v', 'screw']
    # Colors are passed as a list: [blue, red, yellow, red]
    # Relative positions: (dx, dy) from reference point (x, y)
    offsets = [(0, 0), (1, 0), (0, 0), (0, 0)]

    # Place each shape with its corresponding color and offset
    for i, (shape, color, (dx, dy)) in enumerate(zip(shapes, colors, offsets)):
        if shape == 'bridge-h':
            # Horizontal bridge spans (x, y) and (x, y+1)
            put(board, 'bridge-h', color, x + dx, y + dy)
        elif shape == 'bridge-v':
            # Vertical bridge spans (x, y) and (x+1, y)
            put(board, 'bridge-v', color, x + dx, y + dy)
        else:
            put(board, shape, color, x + dx, y + dy)

